-/* @test
- * @bug 8394580
- * @summary Check that binding to 127.0.0.255 succeeds
- * @requires (os.family == "linux")
- * @library /test/lib
- * @build jdk.test.lib.net.IPSupport jtreg.SkippedException
- * @run main BindLoopback
- */
-
-import jdk.test.lib.net.IPSupport;
-import jtreg.SkippedException;
-
-import java.io.IOException;
-import java.net.InetSocketAddress;
-import java.net.StandardProtocolFamily;
-import java.nio.channels.DatagramChannel;
-
-public class BindLoopback {
-
-    public static void main(String[] args) throws IOException {
-        if (!IPSupport.hasIPv4()) {
-            throw new SkippedException("No IPv4 support");
-        }
-        try (DatagramChannel channel = DatagramChannel.open()) {
-            channel.bind(new InetSocketAddress("127.0.0.255", 0));
-        }
-        try (DatagramChannel channel = DatagramChannel.open(StandardProtocolFamily.INET)) {
-            channel.bind(new InetSocketAddress("127.0.0.255", 0));
-        }
-    }
-}

